const items = $input.all();
return items.map(item => {
  const body = item.json.body || item.json;
  const raw = body.result || (Array.isArray(body.results) ? body.results[0] : body) || {};
  return {
    json: {
      rule_name: raw.rule_name || body.search_name || 'Unknown Rule',
      search_name: body.search_name || raw.search_name || '',
      host: raw.host || '',
      user: raw.user || '',
      src_ip: raw.src_ip || '',
      file_hash: raw.file_hash || '',
      _time: raw._time || new Date().toISOString()
    }
  };
});

const alert = $('Normalize Alert').first().json;
const vt = $json;
const abuse = $json;

// VT and AbuseIPDB responses were both flattened onto $json by the preceding
// HTTP Request nodes in this linear chain, so re-read each via its node name
// to avoid ambiguity.
const vtJson = $('VirusTotal Lookup').first().json || {};
const abuseJson = $('AbuseIPDB Lookup').first().json || {};

const vtStats = (vtJson.data && vtJson.data.attributes && vtJson.data.attributes.last_analysis_stats) || {};
const malicious = vtStats.malicious || 0;
const suspicious = vtStats.suspicious || 0;
const totalEngines = malicious + suspicious + (vtStats.harmless || 0) + (vtStats.undetected || 0);

const abuseData = abuseJson.data || {};
const abuseScore = typeof abuseData.abuseConfidenceScore === 'number' ? abuseData.abuseConfidenceScore : 0;
const isTor = !!abuseData.isTor;
const totalReports = abuseData.totalReports || 0;

let score = 0;
const reasons = [];

const maliciousPoints = Math.min(malicious * 6, 60);
const suspiciousPoints = Math.min(suspicious * 2, 10);
if (maliciousPoints) {
  score += maliciousPoints;
  reasons.push(`VirusTotal: ${malicious}/${totalEngines} engines flagged ${alert.file_hash} as malicious`);
}
if (suspiciousPoints) {
  score += suspiciousPoints;
  reasons.push(`VirusTotal: ${suspicious} engines flagged the hash as suspicious`);
}

const abusePoints = Math.round(abuseScore * 0.5);
if (abusePoints) {
  score += abusePoints;
  reasons.push(`AbuseIPDB: ${alert.src_ip} has a ${abuseScore}% abuse confidence score across ${totalReports} reports`);
}
if (isTor) {
  score += 10;
  reasons.push(`AbuseIPDB: ${alert.src_ip} is a known Tor exit node`);
}

score = Math.min(score, 100);
if (reasons.length === 0) {
  reasons.push('No indicators returned a hit from either enrichment source');
}

let severity = 'INFO';
if (score >= 80) severity = 'CRITICAL';
else if (score >= 60) severity = 'HIGH';
else if (score >= 40) severity = 'MEDIUM';
else if (score > 0) severity = 'LOW';

const priorityMap = { CRITICAL: 'Highest', HIGH: 'High', MEDIUM: 'Medium', LOW: 'Low', INFO: 'Lowest' };

return [{
  json: {
    ...alert,
    score,
    severity,
    reasons,
    should_create_ticket: score >= 40,
    jira_priority: priorityMap[severity]
  }
}];

const item = $json;
const summary = `[${item.severity}] ${item.rule_name} — ${item.host || 'unknown host'}`;
const descriptionLines = [
  `Detected by rule: ${item.rule_name}`,
  `Host: ${item.host || 'unknown'}   User: ${item.user || 'unknown'}`,
  `Risk score: ${item.score}/100 (${item.severity})`,
  ...item.reasons,
  `Raw alert time: ${item._time}`
];

return [{
  json: {
    fields: {
      project: { key: $env.JIRA_PROJECT_KEY || 'SOC' },
      summary,
      description: {
        type: 'doc',
        version: 1,
        content: descriptionLines.map(line => ({
          type: 'paragraph',
          content: [{ type: 'text', text: line }]
        }))
      },
      issuetype: { name: 'Incident' },
      priority: { name: item.jira_priority },
      labels: ['soc-automation']
    }
  }
}];
